(async () => {
  try {
    const adapter = window.app.vault.adapter;
    const hbPath = `${window.app.vault.configDir}/plugins/daggerforge/homebrew.js`;
    if (await adapter.exists(hbPath)) {
      const code = await adapter.read(hbPath);
      const mod = { exports: {} };
      new Function("module", "exports", code)(mod, mod.exports);
      const hb = mod.exports;
      if (Array.isArray(hb.ancestries)) _t.push(...hb.ancestries);
      if (Array.isArray(hb.communities)) En.push(...hb.communities);
      console.log("DaggerForge homebrew caricato:", hb.ancestries?.length || 0, "ancestries");
    } else {
      console.warn("DaggerForge: homebrew.js non trovato in", hbPath);
    }
  } catch (e) {
    console.error("Errore caricamento homebrew.js:", e);
  }
})();

